css_snippet:
.article-body {
  font-family: 'Merriweather', serif;
  font-size: 1.125em;
  line-height: 1.6;
  font-feature-settings: "liga" 1, "onum" 1; /* Enable standard ligatures and old-style figures */
}

h2.section-heading {
  font-family: 'Montserrat', sans-serif;
  font-size: 1.8em;
  font-weight: 700;
  font-feature-settings: "smcp" 1; /* Enable small caps */
  text-transform: lowercase; /* Important for 'smcp' */
}
